package tariff
type Rate func(int) int
var base = map[string]Rate{"road": RoadRate, "rail": FlatRailRate}
var contracted = map[string]Rate{"rail": TieredRailRate}
func Resolve(lane string) Rate {
    if rate, ok := contracted[lane]; ok { return rate }
    return base[lane]
}

